function main(): void {
  setTimeout(() => console.log("unref never"), 500).unref();
  const t = setTimeout(() => console.log("kept"), 80);
  console.log(t.hasRef());
  t.unref();
  console.log(t.hasRef());
  t.ref();
  console.log(t.hasRef());
  setTimeout(() => {
    console.log("outer");
    setTimeout(() => {
      console.log("inner");
      setTimeout(() => console.log("innermost"), 0);
    }, 0);
  }, 2);
}
